"""AZ-305 domain 1: Design identity, governance, and monitoring solutions (25–30%)."""
from _az305 import AAC, ML, S, L, anim, cfg, lab, qa, row

anim("az305-monitor-sim", "Logging and monitoring design", ["AZ305-1.1.1", "AZ305-1.1.2", "AZ305-1.1.3"], "Choose log destinations, monitoring features and workspace designs for real requirements.")
anim("az305-authn-sim", "Authentication and identity design", ["AZ305-1.2.1", "AZ305-1.2.2"], "Pick hybrid sign-in methods and identity solutions for employees, partners, customers and workloads.")
anim("az305-authz-sim", "Authorization design", ["AZ305-1.2.3", "AZ305-1.2.4"], "Choose RBAC, custom roles, PIM and ABAC for Azure, and application proxy, Private Access or Domain Services for on-premises.")
anim("az305-secrets-sim", "Secrets, keys and certificates", ["AZ305-1.2.5"], "Choose Key Vault Standard, Premium, Managed HSM or App Configuration for each requirement.")
anim("az305-governance-sim", "Governance design", ["AZ305-1.3.1", "AZ305-1.3.2", "AZ305-1.3.3"], "Decide where policy, billing, lifecycle and metadata belong, and pick compliance and identity-governance tools.")

MON = ML + "azure/azure-monitor/"
ENTRA = ML + "entra/"
GOV = ML + "azure/governance/"

# ================================================================ 1.1 logging and monitoring
L(
    id="az305-monitoring", title="Design logging and monitoring", objectives=["AZ305-1.1.1", "AZ305-1.1.2", "AZ305-1.1.3"], minutes=45,
    objective="Recommend a logging solution (workspaces, tables, retention), a way to route logs (diagnostic settings, data collection rules) and the monitoring features that fit each workload.",
    prereqs=[("Azure Monitor metrics and logs (AZ-104)", "AZ104-5.1.1", "az104-monitor-metrics-logs"), ("Alerts and action groups (AZ-104)", "AZ104-5.1.4", "az104-alerts")],
    foundation=[
        "Monitoring answers two questions: is it healthy right now (metrics, alerts), and what happened (logs).",
        "Azure collects platform metrics automatically. Logs need a decision: which logs, sent where, kept how long, and who may read them.",
        "Most designs use one central Log Analytics workspace, a few diagnostic settings to send logs there, and the right 'insights' feature for each kind of workload.",
    ],
    engineer=[
        "Workspace design: start with a single workspace and add more only for a reason: data residency (a workspace stores data in its region), separate tenants or billing owners (for example customers of a service provider, queried across with Azure Lighthouse), or very different access needs that resource-context RBAC and table-level RBAC cannot meet.",
        "Cost and retention: table plans (Analytics for frequent queries and alerts, Basic for cheaper high-volume troubleshooting logs, Auxiliary for low-cost long-term audit data), interactive retention up to 2 years and long-term retention up to 12 years in total, commitment tiers for predictable ingestion, and data collection rule transformations to drop unneeded columns before ingestion.",
        "Routing: diagnostic settings send resource logs, the activity log and platform metrics to a Log Analytics workspace (query and alert), a storage account (cheap archive), Event Hubs (stream to third-party SIEMs and tools) or an Azure Monitor partner integration. One resource can have several diagnostic settings. For VMs and Arc servers, the Azure Monitor Agent plus data collection rules (DCRs) decide what guest data is collected and where it goes. Apply settings at scale with Azure Policy (DeployIfNotExists).",
        "Monitoring solutions: Application Insights (workspace-based APM with distributed tracing and availability tests), VM insights (performance and dependency map), Container insights and managed Prometheus/Grafana for AKS, Network Watcher (connection monitor, flow logs), storage and network insights, Microsoft Sentinel (SIEM/SOAR on the workspace), Azure Monitor alerts with action groups, and workbooks or dashboards to visualise.",
        "Alerting design: alert on symptoms users feel (failed requests, latency) as well as causes (CPU); use dynamic thresholds for noisy metrics; route with action groups and suppress during maintenance with alert processing rules.",
    ],
    anim=("az305-monitor-sim", "Choose where logs go, which monitoring feature fits, and how many workspaces you need."),
    example=("A retail company's monitoring design", [
        "All subscriptions send activity logs and resource logs to one central workspace in West Europe through diagnostic settings applied by Azure Policy. App teams see only their own resources with resource-context access.",
        "Security audit logs are also sent to a storage account with a 7-year immutable policy, and the SOC streams firewall logs to its existing SIEM through Event Hubs. Web apps use Application Insights; AKS clusters use Container insights.",
    ]),
    config=cfg(["Monitor > Diagnostic settings: choose a resource, add a setting, pick categories and destinations.", "Log Analytics workspace > Tables: set the table plan and retention.", "Monitor > Data collection rules: define what VMs send and where.", "Policy > Definitions: search 'Enable logging by category group' to deploy diagnostic settings at scale."],
               cli="az monitor log-analytics workspace create -g rg-mon -n law-central -l westeurope --retention-time 90\naz monitor diagnostic-settings create --name to-law --resource <resource-id> \\\n  --workspace law-central --logs '[{\"categoryGroup\":\"allLogs\",\"enabled\":true}]'",
               ps="New-AzOperationalInsightsWorkspace -ResourceGroupName rg-mon -Name law-central -Location westeurope -RetentionInDays 90"),
    lab=lab("Design where each log goes and which monitoring feature to use.", [("log-route", "log destination"), ("monitor-tool", "monitoring solution"), ("workspace-design", "workspace design")],
            ["Open each trainer and answer every requirement.", "For a wrong answer, read why the recommended option fits better."],
            ["Query and alerts → Log Analytics; cheap archive → storage; external SIEM → Event Hubs", "Start with one workspace"], ["Creating a workspace per team", "Archiving years of logs in the Analytics plan"]),
    troubleshooting=[("Log costs are much higher than expected.", "Verbose logs ingested into the Analytics plan, and all categories enabled.", "Send only needed categories, use the Basic or Auxiliary plan for high-volume logs, and add DCR transformations."),
                     ("Teams can't find each other's logs, and cross-workspace queries are slow.", "Too many workspaces.", "Consolidate into fewer workspaces and use resource-context RBAC.")],
    comparisons=[("Metrics vs logs", "Metrics are numbers, near real time, kept 93 days; logs are detailed records queried with KQL."), ("Sentinel vs Defender for Cloud", "Sentinel is a SIEM/SOAR for investigation; Defender for Cloud is posture management and workload protection.")],
    misconceptions=[("You need a workspace per application.", "One central workspace with RBAC is usually best."), ("Diagnostic settings are on by default.", "Resource logs are not collected until you create a diagnostic setting.")],
    decisions=["One central workspace unless residency, tenant or billing requires more.", "Route to storage for archive and Event Hubs for external tools.", "Apply diagnostic settings with Azure Policy."],
    docs=[("Design a Log Analytics workspace architecture", MON + "logs/workspace-design"), ("Diagnostic settings in Azure Monitor", MON + "essentials/diagnostic-settings"), ("Application Insights overview", MON + "app/app-insights-overview"), ("What is Microsoft Sentinel?", ML + "azure/sentinel/overview")],
    walk_=("Know what's happening in your Azure estate, keep the logs you need, and pay as little as possible.",
           ["Metrics vs logs", "Where logs can go", "How many workspaces", "Which monitoring feature for which workload"],
           row(0, ("apps", "Apps and resources", "compute"), ("ds", "Diagnostic settings", "service", "what + where"), ("law", "Log Analytics", "database", "query + alert"))
           + row(1, ("st", "Storage account", "storage", "cheap archive"), ("eh", "Event Hubs", "service", "to other tools"), ("ai", "Application Insights", "service", "app performance"))
           + row(2, ("sent", "Microsoft Sentinel", "security", "SIEM"), ("alert", "Alerts", "user", "tell people")),
           [S("problem", "Problem", "Something broke last night. Can you tell what?", "Without a design, logs are scattered, missing or very expensive. You need to decide what to collect, where to send it and who can read it.", add=["apps"]),
            S("concept", "Two signals", "Metrics and logs", "Metrics are numbers collected automatically (CPU %, requests). Logs are detailed records (who signed in, which request failed). Logs must be sent somewhere before you can use them.", learn=[0]),
            S("technique", "Routing", "Diagnostic settings choose what and where", "A diagnostic setting picks log categories and sends them to:\n\n• Log Analytics — to query with KQL and alert\n• a storage account — cheap long-term archive\n• Event Hubs — to stream to another tool (an existing SIEM)", add=["ds", "law", "st", "eh"], edges=[("apps", "ds"), ("ds", "law", "query"), ("ds", "st", "archive"), ("ds", "eh", "stream")], learn=[1], tip="One resource can have several diagnostic settings, for example one to the workspace and one to storage."),
            S("concept", "Workspaces", "One workspace is usually enough", "Add another workspace only for a real reason: data must stay in another region, it belongs to another organisation, or it is billed separately. Teams can still see only their own resources in a shared workspace.", focus=["law"], learn=[2], warn="A workspace per team makes cross-team investigations slow and costly."),
            S("technique", "Features", "Pick the insight for the workload", "Web apps → Application Insights (requests, dependencies, failures). VMs → VM insights. AKS → Container insights. Security → Microsoft Sentinel on the same workspace. Then alerts tell people.", add=["ai", "sent", "alert"], edges=[("apps", "ai"), ("ai", "law"), ("law", "sent"), ("law", "alert")], learn=[3]),
            S("recap", "Recap", "Monitoring design", "Collect, route, keep, protect.", recap=["Metrics automatic; logs need diagnostic settings or DCRs", "Workspace = query; storage = archive; Event Hubs = stream out", "Start with one workspace", "App Insights, VM/Container insights, Sentinel, alerts"])]),
)
qa("AZ305-1.1.1", 2, "scenario", "A company operates in the EU and the US. Regulation requires EU log data to stay in the EU. Which logging design do you recommend?", [("One Log Analytics workspace per geography (EU and US)", "Correct: workspaces store data in their region."), ("One workspace in the US for everything", "EU data would leave the EU."), ("One workspace per application", "Many workspaces without a residency reason add cost and complexity."), ("Send all logs to a storage account only", "You lose querying and alerting.")], "a", "Data residency is a valid reason for more than one workspace.", MON + "logs/workspace-design")
qa("AZ305-1.1.1", 3, "architecture", "Firewall logs are huge, queried only during investigations, and must be kept 2 years at low cost. Alerts are not needed on them. What do you recommend?", [("Ingest them into a table using the Basic logs plan", "Correct: cheaper ingestion for high-volume troubleshooting logs."), ("Analytics plan with 2-year interactive retention", "Most expensive option for rarely queried data."), ("Do not collect them", "They are needed for investigations."), ("Send them to Application Insights", "Not an app telemetry workload.")], "a", "Use table plans to match cost to how logs are used: Analytics for alerting and frequent queries, Basic/Auxiliary for high-volume, rarely queried logs.", MON + "logs/logs-table-plans")
qa("AZ305-1.1.1", 2, "single", "Each application team must see only logs from its own resources in a shared Log Analytics workspace. What do you use?", [("Resource-context access with Azure RBAC on the resources", "Correct."), ("A separate workspace per team", "Not required for access control."), ("Workspace keys shared per team", "Keys do not scope queries."), ("Azure Policy", "Policy does not control log reading.")], "a", "Resource-context RBAC returns only records from resources the user can access; table-level RBAC adds finer control.", MON + "logs/manage-access")
qa("AZ305-1.1.2", 2, "scenario", "The security team uses a third-party SIEM that must receive Azure resource logs in near real time. How do you route them?", [("Diagnostic settings that stream to Event Hubs", "Correct."), ("Diagnostic settings to a storage account", "Archive, not a stream."), ("Export from Log Analytics once a week", "Not near real time."), ("Application Insights", "App telemetry only.")], "a", "Event Hubs is the destination for streaming logs to external systems.", MON + "essentials/diagnostic-settings")
qa("AZ305-1.1.2", 2, "scenario", "Diagnostic settings must be configured on every new key vault in 30 subscriptions, automatically. What do you recommend?", [("An Azure Policy with the DeployIfNotExists effect assigned at a management group", "Correct."), ("A script run manually each month", "Not automatic; misses new vaults."), ("A resource lock", "Locks prevent changes."), ("A data collection rule", "DCRs are for agent-based collection, not resource logs.")], "a", "Built-in 'enable logging by category group' policies deploy diagnostic settings at scale.", GOV + "policy/concepts/effect-deploy-if-not-exists")
qa("AZ305-1.1.2", 2, "configuration", "Windows VMs must send only the System and Application event logs (Error and Warning) to a workspace. What do you configure?", [("Azure Monitor Agent with a data collection rule selecting those events", "Correct."), ("A diagnostic setting on the VM", "Guest OS logs need the agent and a DCR."), ("The legacy Log Analytics agent", "Retired."), ("Boot diagnostics", "Screenshots and serial log only.")], "a", "Data collection rules define which guest data the Azure Monitor Agent collects and where it sends it.", MON + "agents/data-collection-rule-azure-monitor-agent")
qa("AZ305-1.1.3", 2, "scenario", "Users report a web app is slow. You need to see which database or API call takes the longest for each request. What do you recommend?", [("Application Insights with distributed tracing", "Correct."), ("VM insights", "Infrastructure, not request-level traces."), ("Network Watcher", "Network diagnostics."), ("Activity log", "Control-plane events.")], "a", "Application Insights records requests and dependency calls with timing.", MON + "app/app-insights-overview")
qa("AZ305-1.1.3", 2, "scenario", "The SOC needs to correlate security events from Azure, Microsoft 365 and on-premises firewalls and run automated responses. What do you recommend?", [("Microsoft Sentinel", "Correct: SIEM and SOAR."), ("Azure Monitor workbooks", "Visualisation only."), ("Azure Advisor", "Best-practice recommendations."), ("Azure Policy", "Configuration compliance.")], "a", "Sentinel runs on a Log Analytics workspace with connectors, analytics rules and playbooks.", ML + "azure/sentinel/overview")
qa("AZ305-1.1.3", 3, "architecture", "Which TWO features help monitor AKS clusters?", [("Container insights", "Correct."), ("Azure Monitor managed service for Prometheus", "Correct."), ("VM insights dependency map for each pod", "VM insights targets VMs."), ("Azure Advisor score", "Recommendations, not monitoring.")], "ab", "Container insights plus managed Prometheus (and Grafana) are the AKS monitoring stack.", MON + "containers/container-insights-overview")

# ================================================================ 1.2.1–1.2.2 authentication and identity management
L(
    id="az305-authentication", title="Design authentication and identity management", objectives=["AZ305-1.2.1", "AZ305-1.2.2"], minutes=45,
    objective="Recommend an authentication solution (hybrid sign-in, MFA, passwordless, Conditional Access) and an identity management solution for employees, partners, customers and workloads.",
    prereqs=[("Microsoft Entra users and groups (AZ-104)", "AZ104-1.1.1", "az104-entra-users-groups"), ("Self-service password reset (AZ-104)", "AZ104-1.1.5", "az104-sspr")],
    foundation=[
        "Authentication proves who someone is. In Azure that job belongs to Microsoft Entra ID.",
        "Employees often already exist in on-premises Active Directory. You copy them to Entra ID so they use one account everywhere, and decide how their password is checked.",
        "Partners, customers and apps are different kinds of identity, each with its own Entra feature.",
    ],
    engineer=[
        "Hybrid sign-in with Microsoft Entra Connect Sync or Cloud Sync: password hash sync (PHS, recommended default: no on-premises dependency at sign-in, enables leaked-credential detection in ID Protection), pass-through authentication (PTA: agents validate against AD in real time; use when on-premises policies such as logon hours must apply at sign-in), or federation with AD FS (only for requirements Entra ID cannot meet, such as some third-party smart-card or MFA integrations). Seamless SSO gives domain-joined devices silent sign-in.",
        "Strong authentication: MFA through the Authentication methods policy, passwordless (Windows Hello for Business, FIDO2 security keys and passkeys, Microsoft Authenticator), and Conditional Access (Entra ID P1) to require MFA or compliant devices by user, app, location and risk. Risk-based policies use ID Protection (P2). Security defaults suit small tenants without P1.",
        "Identity types: employees (members, synced or cloud-only); partners with B2B collaboration (guests use their own credentials; cross-tenant access settings control trust); customers with Microsoft Entra External ID in an external tenant (customer sign-up, social identity providers; the successor to Azure AD B2C, which is no longer available to new customers); workloads with managed identities (system- or user-assigned) for Azure resources, service principals for apps, and workload identity federation for GitHub Actions, Kubernetes and other OIDC issuers so no secrets are stored.",
        "Identity management at scale: dynamic groups and group-based licensing, administrative units to delegate administration to part of the directory, and Microsoft Entra roles assigned with least privilege.",
    ],
    anim=("az305-authn-sim", "Pick the hybrid sign-in method and the identity solution for each kind of user or workload."),
    example=("A manufacturer moving to Microsoft 365 and Azure", [
        "15,000 AD users sync with Entra Connect Sync and password hash sync, so sign-in keeps working even during a datacenter outage. Conditional Access requires MFA outside the office and compliant devices for admins.",
        "Suppliers access a procurement app as B2B guests; the customer portal uses External ID with email and social sign-up; Azure Functions use managed identities, and GitHub Actions deploy with workload identity federation.",
    ]),
    config=cfg(["Microsoft Entra admin center > Hybrid management > Microsoft Entra Connect: choose sync tool and sign-in method.", "Protection > Conditional Access > Create new policy.", "Protection > Authentication methods > Policies: enable passkeys / Authenticator.", "External Identities > Cross-tenant access settings."],
               cli="az identity create -g rg-app -n id-orders\naz webapp identity assign -g rg-app -n app-orders --identities id-orders",
               ps="New-AzUserAssignedIdentity -ResourceGroupName rg-app -Name id-orders -Location westeurope",
               perms=("Hybrid Identity Administrator for Connect; Conditional Access Administrator for policies",)),
    lab=lab("Pick the sign-in method and identity type for each requirement.", [("hybrid-auth", "hybrid sign-in method"), ("identity-type", "identity solution")],
            ["Answer every case in both trainers.", "Compare password hash sync with pass-through authentication."],
            ["Password hash sync is the default", "Managed identities and workload identity federation remove secrets"], ["Choosing federation without a requirement for it", "Using B2B for millions of consumers"]),
    troubleshooting=[("Users can't sign in when the on-premises datacenter is down.", "Pass-through authentication or federation depends on on-premises servers.", "Enable password hash sync (also as a backup method)."),
                     ("A pipeline's client secret expired and deployments failed.", "Secrets need rotation.", "Use workload identity federation (no secret) for GitHub Actions or Azure DevOps.")],
    comparisons=[("B2B vs External ID (customers)", "B2B: partners as guests in your workforce tenant; External ID: customer accounts in an external tenant for your apps."), ("System- vs user-assigned managed identity", "System-assigned lives and dies with one resource; user-assigned is a standalone identity shared by several resources.")],
    misconceptions=[("Password hash sync sends passwords to the cloud.", "It syncs a hash of the password hash; the password itself never leaves."), ("Federation is more secure by default.", "It adds infrastructure and failure points; PHS plus MFA and Conditional Access is Microsoft's recommendation.")],
    decisions=["PHS by default; PTA or federation only for specific requirements.", "Conditional Access with MFA or passwordless for everyone.", "No secrets for workloads: managed identity or workload identity federation."],
    docs=[("Choose the right authentication method for hybrid identity", ENTRA + "identity/hybrid/connect/choose-ad-authn"), ("What is Conditional Access?", ENTRA + "identity/conditional-access/overview"), ("External Identities overview", ENTRA + "external-id/external-identities-overview"), ("Managed identities for Azure resources", ENTRA + "identity/managed-identities-azure-resources/overview")],
    walk_=("Give every person and app a trusted identity, with strong sign-in and no secrets in code.",
           ["Hybrid sign-in: PHS, PTA, federation", "Strong authentication and Conditional Access", "Partners and customers", "Identities for workloads"],
           row(0, ("ad", "On-premises AD", "identity"), ("sync", "Entra Connect", "service", "sync users"), ("entra", "Microsoft Entra ID", "identity"))
           + row(1, ("ca", "Conditional Access", "security", "MFA, device, risk"), ("guest", "Partner (B2B)", "user"), ("cust", "Customer (External ID)", "user"))
           + row(2, ("app", "Azure Function", "compute"), ("mi", "Managed identity", "security", "no secrets"), ("kv", "Key Vault", "security")),
           [S("problem", "Problem", "Many kinds of users, one sign-in system", "Employees are in on-premises AD, partners have their own accounts, customers sign up online, and apps need to call Azure. Each needs the right identity.", add=["entra"]),
            S("technique", "Hybrid", "Sync employees and choose how passwords are checked", "Entra Connect copies users from AD. Then:\n\n• Password hash sync — the cloud checks a hash; works even if on-premises is down (recommended)\n• Pass-through — on-premises agents check the password live\n• Federation — on-premises servers do the sign-in (only when you must)", add=["ad", "sync"], edges=[("ad", "sync"), ("sync", "entra")], learn=[0]),
            S("technique", "Strong sign-in", "MFA and Conditional Access", "Conditional Access policies decide when to ask for MFA, require a compliant device or block risky sign-ins. Passwordless methods (passkeys, Windows Hello, Authenticator) are the strongest and easiest.", add=["ca"], edges=[("entra", "ca")], learn=[1], tip="Conditional Access needs Entra ID P1; risk-based policies need P2."),
            S("concept", "Outsiders", "Partners and customers", "Partners: B2B guests sign in with their own work account. Customers: Microsoft Entra External ID gives your app sign-up and sign-in with email or social accounts.", add=["guest", "cust"], edges=[("guest", "entra", "guest"), ("cust", "entra", "external tenant")], learn=[2]),
            S("technique", "Workloads", "Apps get identities too", "An Azure Function uses a managed identity to reach Key Vault — no password to store or rotate. Pipelines outside Azure (GitHub Actions) use workload identity federation.", add=["app", "mi", "kv"], edges=[("app", "mi"), ("mi", "kv", "token")], learn=[3]),
            S("recap", "Recap", "Authentication design", "One identity system, strong sign-in, no secrets.", recap=["PHS by default (PTA/federation only if required)", "Conditional Access + MFA/passwordless", "B2B for partners, External ID for customers", "Managed identity / workload identity federation for apps"])]),
)
qa("AZ305-1.2.1", 2, "scenario", "You sync 10,000 users from AD. Sign-in must keep working if the on-premises datacenter is offline, and leaked passwords must be detected. Which method?", [("Password hash sync", "Correct."), ("Pass-through authentication", "Depends on on-premises agents."), ("Federation with AD FS", "Depends on on-premises servers."), ("Cloud-only accounts", "Users must keep their AD identity.")], "a", "PHS has no on-premises dependency at sign-in and enables leaked-credential detection.", ENTRA + "identity/hybrid/connect/choose-ad-authn")
qa("AZ305-1.2.1", 2, "scenario", "Admins must use MFA, and access to the Azure portal from unmanaged devices must be blocked. What do you recommend?", [("Conditional Access policies (Entra ID P1)", "Correct."), ("Security defaults", "Cannot require compliant devices."), ("Per-user MFA only", "No device conditions."), ("Azure Policy", "Not for sign-in.")], "a", "Conditional Access combines user, app, device and location conditions.", ENTRA + "identity/conditional-access/overview")
qa("AZ305-1.2.1", 3, "scenario", "Users must sign in without passwords using phishing-resistant authentication on shared kiosk PCs. What do you recommend?", [("FIDO2 security keys (passkeys)", "Correct: phishing-resistant and not tied to one PC."), ("SMS codes", "Not phishing-resistant."), ("Windows Hello for Business", "Bound to a personal device."), ("Security questions", "Weak and not a sign-in method.")], "a", "FIDO2 keys and passkeys are phishing-resistant and portable.", ENTRA + "identity/authentication/concept-authentication-passwordless")
qa("AZ305-1.2.2", 2, "scenario", "A consumer app needs sign-up and sign-in for millions of customers with email or Google accounts. What do you recommend?", [("Microsoft Entra External ID in an external tenant", "Correct."), ("B2B collaboration guests in the workforce tenant", "Meant for partners."), ("Create member users for each customer", "Not scalable or appropriate."), ("Managed identities", "For Azure resources.")], "a", "External ID is the customer identity solution (successor to Azure AD B2C).", ENTRA + "external-id/external-identities-overview")
qa("AZ305-1.2.2", 2, "scenario", "A GitHub Actions workflow deploys to Azure. Security forbids long-lived client secrets. What do you recommend?", [("Workload identity federation on an app registration or user-assigned managed identity", "Correct."), ("A client secret valid for 2 years", "Long-lived secret."), ("A user account with MFA", "Pipelines cannot do MFA."), ("A storage account key", "Unrelated.")], "a", "Federated credentials trust GitHub's OIDC token, so no secret is stored.", ENTRA + "workload-id/workload-identity-federation")
qa("AZ305-1.2.2", 2, "single", "Several web apps must use the same identity to access a database, and it must survive if one app is deleted. Which identity?", [("A user-assigned managed identity", "Correct."), ("A system-assigned managed identity per app", "Deleted with each app and not shared."), ("A shared SQL login in app settings", "A secret to manage."), ("A B2B guest", "For people.")], "a", "User-assigned identities are standalone resources that can be attached to many resources.", ENTRA + "identity/managed-identities-azure-resources/overview")

# ================================================================ 1.2.3–1.2.4 authorization
L(
    id="az305-authorization", title="Design authorization for Azure and on-premises resources", objectives=["AZ305-1.2.3", "AZ305-1.2.4"], minutes=40,
    objective="Recommend how people and workloads are authorized to Azure resources (RBAC, custom roles, PIM, ABAC) and to on-premises resources (application proxy, Private Access, Domain Services).",
    prereqs=[("Azure RBAC (AZ-104)", "AZ104-1.2.2", "az104-rbac")],
    foundation=[
        "Authorization decides what a signed-in identity may do.",
        "For Azure resources the rule is least privilege: the smallest role, at the smallest scope, for the shortest time.",
        "On-premises apps can use Microsoft Entra ID as their front door too, so remote users get MFA without a traditional VPN.",
    ],
    engineer=[
        "Azure RBAC design: assign roles to groups, not users; use built-in roles first; scope at management group, subscription, resource group or resource; create custom roles (Actions/NotActions, DataActions) only when no built-in role fits; avoid Owner and User Access Administrator except for a few, and use the Role Based Access Control Administrator role with conditions to limit which roles others can assign.",
        "Privileged Identity Management (Entra ID P2 or ID Governance): make admin roles eligible rather than permanent, with time-bound activation, MFA, justification, approval and access reviews. Covers Entra roles, Azure roles and groups (PIM for Groups).",
        "Attribute-based access control (ABAC) adds conditions to role assignments, for example Storage Blob Data Reader only for blobs with the index tag Project=Alpha. Data-plane access (Storage Blob Data, Key Vault Secrets User, Cosmos DB data roles) is separate from control-plane roles like Contributor.",
        "On-premises resources: Microsoft Entra application proxy publishes internal web apps (with pre-authentication, Conditional Access, and Kerberos constrained delegation for Windows-integrated apps) through outbound-only connectors. Microsoft Entra Private Access (Global Secure Access) provides Zero Trust network access to private apps on any port, replacing VPNs. Microsoft Entra Domain Services gives a managed domain (LDAP, Kerberos, NTLM, Group Policy) for legacy apps moved to Azure, without running domain controllers. Entra Kerberos enables identity-based access to Azure Files for hybrid users.",
    ],
    anim=("az305-authz-sim", "Choose the right authorization approach for Azure and for on-premises apps."),
    example=("Least privilege at a bank", [
        "Cloud engineers are eligible for Contributor on their landing-zone subscriptions through PIM, activated for 4 hours with justification; Owner requires approval. A custom 'VM Operator' role lets the service desk only start and restart VMs.",
        "The legacy HR intranet is published with application proxy and Conditional Access, so staff reach it from home with MFA and no VPN.",
    ]),
    config=cfg(["Subscription > Access control (IAM) > Add role assignment; Conditions tab for ABAC.", "Microsoft Entra admin center > Identity governance > Privileged Identity Management > Azure resources.", "Microsoft Entra admin center > Applications > Enterprise applications > Application proxy."],
               cli="az role definition create --role-definition @vm-operator.json\naz role assignment create --assignee-object-id <group-id> --assignee-principal-type Group --role \"VM Operator\" --scope /subscriptions/<sub>/resourceGroups/rg-app",
               ps="New-AzRoleDefinition -InputFile vm-operator.json"),
    lab=lab("Choose how to authorize access in Azure and on-premises.", [("authz-azure", "Azure authorization approach"), ("authz-onprem", "on-premises access solution")],
            ["Answer every case in both trainers."], ["PIM for standing admin access", "Application proxy for on-premises web apps"], ["Giving Owner permanently", "Opening inbound ports for remote access"]),
    troubleshooting=[("An operator can delete VMs although they should only restart them.", "Contributor assigned for convenience.", "Create a custom role with only start/restart/read actions."),
                     ("A user is Contributor on a storage account but cannot read blobs with Entra auth.", "Contributor is control plane only.", "Assign a Storage Blob Data role (data plane).")],
    comparisons=[("RBAC vs Azure Policy", "RBAC controls who can act; Policy controls what resource configurations are allowed."), ("Application proxy vs Private Access", "Application proxy publishes web apps; Private Access gives network-level Zero Trust access to any private app or port.")],
    misconceptions=[("Global Administrator can manage all Azure resources by default.", "Entra roles and Azure RBAC are separate; Global Admins must elevate access to get User Access Administrator."), ("Custom roles are always better.", "Built-in roles are maintained by Microsoft; use custom only when needed.")],
    decisions=["Groups + built-in roles + narrow scope.", "PIM for every privileged role.", "Publish on-premises apps through Entra (application proxy or Private Access) instead of VPN where possible."],
    docs=[("What is Azure RBAC?", ML + "azure/role-based-access-control/overview"), ("What is Privileged Identity Management?", ENTRA + "id-governance/privileged-identity-management/pim-configure"), ("What is Azure ABAC?", ML + "azure/role-based-access-control/conditions-overview"), ("Microsoft Entra application proxy", ENTRA + "identity/app-proxy/overview-what-is-app-proxy"), ("Microsoft Entra Private Access", ENTRA + "global-secure-access/concept-private-access"), ("Microsoft Entra Domain Services", ENTRA + "identity/domain-services/overview")],
    walk_=("Give exactly the access that is needed, only when it is needed — in Azure and on-premises.",
           ["Least privilege with RBAC", "Just-in-time admin with PIM", "Conditions (ABAC) and data-plane roles", "On-premises apps through Entra"],
           row(0, ("grp", "Ops group", "user"), ("role", "Role + scope", "security", "who can do what where"), ("rg", "Resource group", "service"))
           + row(1, ("pim", "PIM", "security", "eligible, time-bound"), ("abac", "ABAC condition", "security", "tag = Alpha"), ("blob", "Blobs", "storage"))
           + row(2, ("remote", "Remote user", "user"), ("proxy", "Application proxy", "service", "Entra pre-auth"), ("intranet", "On-premises web app", "compute")),
           [S("problem", "Problem", "Too many people have too much access", "Owner everywhere is easy and dangerous. Design so each person gets only what they need.", add=["grp"]),
            S("technique", "RBAC", "Role + scope, assigned to a group", "Pick the narrowest built-in role, assign it to a group, at the smallest scope (resource group rather than subscription). Create a custom role only if no built-in role fits.", add=["role", "rg"], edges=[("grp", "role"), ("role", "rg")], learn=[0]),
            S("technique", "PIM", "Admin rights only when needed", "Privileged Identity Management makes roles 'eligible'. Admins activate them for a few hours, with MFA, a reason and sometimes approval.", add=["pim"], edges=[("pim", "role", "activate")], learn=[1]),
            S("concept", "Conditions", "Finer control with ABAC", "Conditions on a role assignment can check attributes, for example: may read only blobs tagged Project=Alpha. Remember that reading data needs data roles such as Storage Blob Data Reader; Contributor is not enough.", add=["abac", "blob"], edges=[("abac", "blob")], learn=[2]),
            S("technique", "On-premises", "Entra as the front door for internal apps", "Application proxy publishes an internal web app through an outbound connector: users sign in with Entra ID and MFA, and no inbound ports open. Private Access does the same for any private app or port, replacing the VPN.", add=["remote", "proxy", "intranet"], edges=[("remote", "proxy"), ("proxy", "intranet", "connector")], learn=[3]),
            S("recap", "Recap", "Authorization design", "Least privilege, just in time.", recap=["Built-in role, group, narrow scope", "PIM for privileged roles", "ABAC conditions; data roles for data", "Application proxy / Private Access for on-premises"])]),
)
qa("AZ305-1.2.3", 2, "scenario", "Engineers should become Contributor on production only when needed, for at most 4 hours, with a justification. What do you recommend?", [("Privileged Identity Management eligible assignments", "Correct."), ("Permanent Contributor with an access review", "Still standing access."), ("A resource lock", "Locks do not grant access."), ("Azure Policy", "Not for permissions.")], "a", "PIM provides just-in-time, time-bound activation with justification and approval.", ENTRA + "id-governance/privileged-identity-management/pim-configure")
qa("AZ305-1.2.3", 2, "scenario", "Support staff must only start, stop and restart VMs in one resource group. No built-in role is that narrow. What do you do?", [("Create a custom role with those actions and assign it to their group at the resource group", "Correct."), ("Assign Virtual Machine Contributor", "Too broad."), ("Assign Owner with a lock", "Far too broad."), ("Use Azure Policy", "Policy does not grant actions.")], "a", "Custom roles list exactly the allowed actions; assign to a group at the narrowest scope.", ML + "azure/role-based-access-control/custom-roles")
qa("AZ305-1.2.3", 3, "scenario", "In a shared container, users from each project may read only blobs tagged with their project. What do you recommend?", [("Storage Blob Data Reader with an ABAC condition on the blob index tag", "Correct."), ("One SAS per user", "Hard to manage and not identity-based."), ("Contributor on the account", "Control plane only, too broad."), ("Separate storage accounts per user", "Unnecessary.")], "a", "ABAC conditions filter data access by attributes such as blob index tags.", ML + "azure/role-based-access-control/conditions-overview")
qa("AZ305-1.2.4", 2, "scenario", "Remote employees need an on-premises intranet site with MFA. The network team will not open inbound firewall ports. What do you recommend?", [("Microsoft Entra application proxy", "Correct: outbound connectors with Entra pre-authentication."), ("Publish the site on a public IP", "Requires inbound ports."), ("Microsoft Entra Domain Services", "A managed domain, not remote access."), ("B2B collaboration", "For external users.")], "a", "Application proxy publishes on-premises web apps securely.", ENTRA + "identity/app-proxy/overview-what-is-app-proxy")
qa("AZ305-1.2.4", 2, "scenario", "A legacy app moved to Azure VMs requires LDAP and Kerberos. The company wants no domain controllers to patch. What do you recommend?", [("Microsoft Entra Domain Services", "Correct."), ("Domain controllers on Azure VMs", "Must be managed and patched."), ("Application proxy", "Publishes web apps; does not provide LDAP."), ("Conditional Access", "Not a directory service.")], "a", "Domain Services is a managed domain compatible with LDAP, Kerberos and NTLM.", ENTRA + "identity/domain-services/overview")
qa("AZ305-1.2.4", 3, "scenario", "The company wants to replace its VPN so remote users reach private apps on various TCP ports, with Conditional Access per app. What do you recommend?", [("Microsoft Entra Private Access", "Correct: Zero Trust network access per app."), ("Point-to-site VPN", "The thing being replaced; network-wide access."), ("Application proxy", "Web apps only."), ("Azure Bastion", "VM admin sessions only.")], "a", "Private Access (Global Secure Access) gives per-app access to private resources on any port.", ENTRA + "global-secure-access/concept-private-access")

# ================================================================ 1.2.5 secrets, certificates and keys
L(
    id="az305-secrets", title="Design secrets, certificates and keys management", objectives=["AZ305-1.2.5"], minutes=30,
    objective="Recommend how to store and use secrets, certificates and encryption keys: Key Vault tiers, Managed HSM, access model, rotation and network isolation.",
    prereqs=[("Storage account encryption (AZ-104)", "AZ104-2.2.4", "az104-storage-accounts")],
    foundation=[
        "Passwords, connection strings, certificates and encryption keys must never live in code or config files.",
        "Azure Key Vault stores them centrally. Apps read them with their managed identity, so nothing secret is written down.",
        "If regulation demands dedicated hardware for keys, use Managed HSM.",
    ],
    engineer=[
        "Tiers: Key Vault Standard (secrets, certificates, software-protected keys); Key Vault Premium (adds HSM-protected keys in multi-tenant HSMs); Managed HSM (single-tenant HSM pool, FIPS 140-3 Level 3 validated, you control the security domain) for the strictest key custody needs.",
        "Access: use the Azure RBAC permission model (Key Vault Secrets User, Crypto Service Encryption User, Key Vault Administrator) rather than legacy access policies; give apps managed identities; separate the management plane (create vaults) from the data plane (read secrets).",
        "Protection: soft delete (always on, 7–90 days) and purge protection (cannot be turned off once enabled; required for customer-managed keys in many services); private endpoints and disabled public network access; logging with diagnostic settings; Defender for Key Vault.",
        "Lifecycle: key rotation policies, certificate auto-renewal with integrated CAs, Event Grid notifications for near-expiry. Design one vault per application per environment per region to limit blast radius and throttling. App settings in App Service and Functions can use Key Vault references; App Configuration holds non-secret settings and references Key Vault for secrets.",
    ],
    anim=("az305-secrets-sim", "Choose Key Vault Standard, Premium, Managed HSM or App Configuration."),
    example=("Customer-managed keys for a payments platform", [
        "Storage and SQL use customer-managed keys from Key Vault Premium with purge protection and a yearly rotation policy. Each app and environment has its own vault, reached through private endpoints.",
        "The card-tokenisation service, which must meet single-tenant HSM requirements, uses Managed HSM.",
    ]),
    config=cfg(["Create a resource > Key Vault: pricing tier, soft delete days, purge protection, permission model = Azure RBAC, Networking = private endpoint.", "Key vault > Keys > Rotation policy.", "App Service > Environment variables: @Microsoft.KeyVault(SecretUri=...)."],
               cli="az keyvault create -g rg-app -n kv-orders-prod-weu --sku premium --enable-purge-protection true --enable-rbac-authorization true --public-network-access Disabled\naz role assignment create --assignee <identity-principal-id> --role \"Key Vault Secrets User\" --scope <vault-id>",
               ps="New-AzKeyVault -ResourceGroupName rg-app -Name kv-orders-prod-weu -Location westeurope -Sku Premium -EnablePurgeProtection"),
    lab=lab("Choose where secrets, keys and settings belong.", [("secrets", "secrets service")], ["Answer every case."], ["Premium for HSM-backed keys; Managed HSM for single-tenant"], ["Storing feature flags in Key Vault", "Sharing one vault across every app and environment"]),
    troubleshooting=[("Enabling customer-managed keys on storage fails.", "Purge protection or soft delete not enabled on the vault, or the storage identity lacks key permissions.", "Enable purge protection and grant Key Vault Crypto Service Encryption User."),
                     ("Apps get HTTP 429 from Key Vault at startup.", "Too many reads against one vault.", "Cache secrets in the app and split vaults per app.")],
    comparisons=[("Key Vault Premium vs Managed HSM", "Premium: HSM-backed keys in a multi-tenant service. Managed HSM: dedicated single-tenant HSM pool, you own the security domain."), ("Key Vault vs App Configuration", "Key Vault for secrets; App Configuration for settings and feature flags.")],
    misconceptions=[("Soft delete can be disabled.", "It is always on for new vaults."), ("Access policies and RBAC are the same.", "RBAC is the recommended model, with fine-grained, scope-based roles.")],
    decisions=["Vault per app, per environment, per region.", "RBAC permission model + managed identities.", "Purge protection and private endpoints for production."],
    docs=[("About Azure Key Vault", ML + "azure/key-vault/general/overview"), ("Key Vault best practices", ML + "azure/key-vault/general/best-practices"), ("What is Managed HSM?", ML + "azure/key-vault/managed-hsm/overview")],
    walk_=("Keep every secret, certificate and key in one safe place that apps can reach without passwords.",
           ["Key Vault tiers and Managed HSM", "Access with managed identities and RBAC", "Protection: soft delete, purge protection, private access", "Rotation and one vault per app"],
           row(0, ("app", "Web app", "compute"), ("mi", "Managed identity", "security"), ("kv", "Key Vault", "security", "secrets, certs, keys"))
           + row(1, ("hsm", "Managed HSM", "security", "single-tenant"), ("pe", "Private endpoint", "network"), ("rot", "Rotation policy", "service"))
           + row(2, ("cfg", "App Configuration", "service", "settings + flags")),
           [S("problem", "Problem", "A connection string was committed to Git", "Secrets in code leak. Design a place where secrets live and a way for apps to read them without another secret.", add=["app"]),
            S("concept", "Tiers", "Pick the vault", "Key Vault Standard: secrets, certificates and software keys. Premium: adds keys protected by hardware security modules. Managed HSM: your own single-tenant HSM pool for the strictest rules.", add=["kv", "hsm"], learn=[0]),
            S("technique", "Access", "Managed identity + RBAC", "The app's managed identity gets the Key Vault Secrets User role on its vault. No password anywhere.", add=["mi"], edges=[("app", "mi"), ("mi", "kv", "read secret")], learn=[1]),
            S("technique", "Protect", "Soft delete, purge protection, private endpoint", "Soft delete keeps deleted items for 7–90 days; purge protection stops anyone destroying them early. A private endpoint keeps the vault off the internet.", add=["pe"], edges=[("pe", "kv")], learn=[2], warn="Purge protection cannot be turned off once enabled — that is the point."),
            S("technique", "Lifecycle", "Rotate, and keep settings separate", "Rotation policies renew keys and certificates automatically. Use one vault per app, environment and region. Non-secret settings and feature flags go in App Configuration, which can reference Key Vault.", add=["rot", "cfg"], edges=[("rot", "kv"), ("cfg", "kv", "reference")], learn=[3]),
            S("recap", "Recap", "Secrets design", "Central, private, rotated.", recap=["Standard / Premium (HSM keys) / Managed HSM", "Managed identity + RBAC roles", "Soft delete + purge protection + private endpoint", "Rotate; vault per app/env/region"])]),
)
qa("AZ305-1.2.5", 2, "scenario", "Customer-managed keys must be protected by HSMs at the lowest cost, without dedicated hardware. Which service?", [("Key Vault Premium", "Correct."), ("Key Vault Standard", "Software-protected keys only."), ("Managed HSM", "Single-tenant and more expensive."), ("App Configuration", "Not for keys.")], "a", "Premium adds HSM-protected keys to Key Vault.", ML + "azure/key-vault/general/overview")
qa("AZ305-1.2.5", 2, "scenario", "A web app must read a database password from Key Vault without storing any credential. What do you recommend?", [("Enable a managed identity on the app and grant it Key Vault Secrets User", "Correct."), ("Store the vault's access key in app settings", "Key Vault has no shared access key; and that would be a secret."), ("Grant the app Owner on the vault", "Too much access."), ("Make the vault public", "Access still needs authorization.")], "a", "Managed identity + RBAC data role is the standard pattern.", ML + "azure/key-vault/general/rbac-guide")
qa("AZ305-1.2.5", 3, "multiple", "Which TWO settings help ensure keys used for customer-managed encryption cannot be permanently destroyed by a malicious admin?", [("Soft delete", "Correct: deleted keys can be recovered."), ("Purge protection", "Correct: prevents permanent deletion during retention."), ("Standard tier", "Unrelated to deletion."), ("Access policies instead of RBAC", "Does not prevent purge.")], "ab", "Soft delete plus purge protection keep deleted keys recoverable for the retention period.", ML + "azure/key-vault/general/soft-delete-overview")

# ================================================================ 1.3 governance
L(
    id="az305-governance", title="Design governance", objectives=["AZ305-1.3.1", "AZ305-1.3.2", "AZ305-1.3.3"], minutes=45,
    objective="Recommend a structure of management groups, subscriptions and resource groups with a tagging strategy, a compliance solution, and an identity governance solution.",
    prereqs=[("Management groups (AZ-104)", "AZ104-1.3.7", "az104-management-groups"), ("Azure Policy and tags (AZ-104)", "AZ104-1.3.1", "az104-policy-tags")],
    foundation=[
        "Governance keeps a growing Azure estate organised, compliant and affordable.",
        "Think of four levels: management groups (rules for many subscriptions), subscriptions (billing and limits), resource groups (things that live and die together) and tags (labels for reporting).",
        "Then decide how to enforce rules (Azure Policy), prove compliance, and keep people's access right over time.",
    ],
    engineer=[
        "Hierarchy: keep management groups shallow (up to six levels below the tenant root) and organised by policy needs, not the org chart. The Azure landing zone reference uses Platform (Identity, Management, Connectivity), Landing zones (Corp, Online), Sandbox and Decommissioned. Subscriptions are units of scale, billing and isolation (quotas, limits, RBAC boundary); separate production from non-production. Resource groups hold resources with the same lifecycle; a resource belongs to one group.",
        "Tagging: define a small mandatory set (for example CostCenter, Environment, Owner, Application) and enforce it with Azure Policy (Require a tag, Inherit a tag from the resource group or subscription with Modify). Tags are not inherited by default. Cost Management can group and allocate costs by tag.",
        "Compliance: Azure Policy initiatives (built-in regulatory initiatives such as ISO 27001, NIST, PCI DSS) assigned at management groups with Deny, Audit, Modify and DeployIfNotExists; exemptions for justified exceptions; Defender for Cloud's regulatory compliance dashboard to report; resource locks for critical resources; Microsoft Purview Compliance Manager for Microsoft 365 and data compliance. Azure Blueprints is deprecated: use template specs, deployment stacks and policy instead.",
        "Identity governance (Microsoft Entra ID Governance / P2): access reviews (recurring certification of group, app and role access, including guests), entitlement management (access packages with approval, expiry and connected organisations), Privileged Identity Management, lifecycle workflows (joiner-mover-leaver automation) and terms of use.",
    ],
    anim=("az305-governance-sim", "Decide where each governance control belongs and which tool proves compliance."),
    example=("A landing-zone hierarchy for a holding company", [
        "Under the tenant root: Platform (identity, management, connectivity subscriptions), Landing zones with Corp and Online, Sandbox and Decommissioned. 'Allowed locations' and 'Require tag CostCenter' are assigned at the top management group; Corp denies public IPs.",
        "Quarterly access reviews remove guests who no longer need access, contractors get time-limited access packages, and lifecycle workflows disable leavers on their last day.",
    ]),
    config=cfg(["Management groups: create the hierarchy and move subscriptions.", "Policy > Assignments: assign initiatives at management groups; Exemptions.", "Defender for Cloud > Regulatory compliance.", "Microsoft Entra admin center > Identity governance: access reviews, entitlement management, lifecycle workflows."],
               cli="az account management-group create --name mg-landingzones --parent mg-contoso\naz policy assignment create --name require-costcenter --scope /providers/Microsoft.Management/managementGroups/mg-contoso \\\n  --policy \"Require a tag on resources\" --params '{\"tagName\":{\"value\":\"CostCenter\"}}'",
               ps="New-AzManagementGroup -GroupName mg-landingzones -ParentId /providers/Microsoft.Management/managementGroups/mg-contoso"),
    lab=lab("Place governance controls and pick compliance and identity-governance tools.", [("hierarchy", "governance level"), ("compliance", "compliance solution"), ("id-governance", "identity governance feature")],
            ["Answer every case in the three trainers."], ["Policy at management groups; billing at subscriptions", "Access reviews and access packages for people"], ["Mirroring the org chart in management groups", "Expecting tags to inherit automatically"]),
    troubleshooting=[("Cost reports show many resources with no CostCenter.", "Tags not enforced, and not inherited.", "Assign 'Require a tag' (Deny) for new resources and 'Inherit a tag from the resource group' (Modify) with remediation."),
                     ("A policy blocks a justified exception for one sandbox.", "No exemption.", "Create a policy exemption (Waiver) with an expiry date.")],
    comparisons=[("Management group vs subscription", "Management groups organise and apply policy/RBAC; subscriptions are the billing, quota and isolation boundary."), ("Access reviews vs PIM", "Access reviews certify existing access periodically; PIM makes privileged access just-in-time.")],
    misconceptions=[("Tags flow down from resource groups automatically.", "Only with a Modify policy."), ("Management groups should mirror departments.", "Design them around policy and access needs.")],
    decisions=["Shallow, policy-driven management group hierarchy (landing zones).", "Mandatory tags enforced by policy.", "Regulatory initiatives + Defender for Cloud reporting.", "Access reviews, access packages and lifecycle workflows for people."],
    docs=[("Management group design (Cloud Adoption Framework)", ML + "azure/cloud-adoption-framework/ready/landing-zone/design-area/resource-org-management-groups"), ("Azure Policy overview", GOV + "policy/overview"), ("Regulatory compliance in Defender for Cloud", ML + "azure/defender-for-cloud/regulatory-compliance-dashboard"), ("Microsoft Entra ID Governance", ENTRA + "id-governance/identity-governance-overview"), ("Define your tagging strategy", ML + "azure/cloud-adoption-framework/ready/azure-best-practices/resource-tagging")],
    walk_=("Organise subscriptions so rules, costs and access stay under control as you grow.",
           ["Management groups, subscriptions, resource groups, tags", "A tagging strategy enforced by policy", "Proving compliance", "Keeping people's access right"],
           row(0, ("root", "Tenant root group", "service"), ("plat", "Platform", "service", "identity, network"), ("lz", "Landing zones", "service", "Corp, Online"))
           + row(1, ("sub", "Subscription", "cost", "billing + quotas"), ("rg", "Resource group", "service", "same lifecycle"), ("tag", "Tags", "cost", "CostCenter, Env"))
           + row(2, ("pol", "Azure Policy", "security", "deny, audit, modify"), ("dfc", "Defender for Cloud", "security", "compliance view"), ("rev", "Access reviews", "identity")),
           [S("problem", "Problem", "Forty subscriptions and no rules", "Resources appear in any region, nobody knows who pays, and old access never goes away.", add=["root"]),
            S("concept", "Hierarchy", "Four levels, four jobs", "Management groups: apply policy and access to many subscriptions. Subscriptions: billing and limits. Resource groups: things deployed and deleted together. Tags: labels for reports.", add=["plat", "lz", "sub", "rg"], edges=[("root", "plat"), ("root", "lz"), ("lz", "sub"), ("sub", "rg")], learn=[0], tip="Organise management groups by the rules they need, not by the org chart."),
            S("technique", "Tags", "A small, enforced set of tags", "Choose a few mandatory tags (CostCenter, Environment, Owner). Azure Policy requires them on new resources and can copy them from the resource group, because tags are not inherited by themselves.", add=["tag", "pol"], edges=[("pol", "tag", "require / inherit")], learn=[1]),
            S("technique", "Compliance", "Enforce with policy, report with Defender", "Assign built-in regulatory initiatives at management groups. Defender for Cloud shows how you score against standards like ISO 27001 or PCI DSS.", add=["dfc"], edges=[("pol", "lz", "assigned"), ("dfc", "pol", "reports")], learn=[2]),
            S("technique", "People", "Identity governance", "Access reviews ask owners every quarter whether access is still needed. Access packages give time-limited bundles of access. PIM keeps admin rights just-in-time. Lifecycle workflows handle joiners and leavers.", add=["rev"], learn=[3]),
            S("recap", "Recap", "Governance design", "Structure, rules, proof, people.", recap=["MG = policy/RBAC; subscription = billing; RG = lifecycle; tags = reporting", "Mandatory tags via Policy (Require + Inherit)", "Regulatory initiatives + Defender for Cloud", "Access reviews, access packages, PIM, lifecycle workflows"])]),
)
qa("AZ305-1.3.1", 2, "scenario", "All production subscriptions must allow only EU regions, and new production subscriptions must get the rule automatically. Where do you assign the policy?", [("On a management group that contains the production subscriptions", "Correct: new subscriptions placed there inherit it."), ("On each production subscription", "New subscriptions would be missed."), ("On each resource group", "Too granular."), ("On the tenant root group for all subscriptions", "Would also restrict non-production.")], "a", "Policies assigned at a management group apply to all subscriptions under it, now and in future.", GOV + "management-groups/overview")
qa("AZ305-1.3.1", 2, "scenario", "Finance needs costs by cost center. Resource groups already have a CostCenter tag, but resources inside often don't. What do you recommend?", [("An 'Inherit a tag from the resource group' policy with Modify and a remediation task", "Correct."), ("Nothing: tags are inherited automatically", "They are not."), ("A separate subscription per cost center", "Heavy change for a reporting need."), ("Resource locks", "Unrelated.")], "a", "Modify policies add or copy tags; remediation fixes existing resources.", ML + "azure/azure-resource-manager/management/tag-policies")
qa("AZ305-1.3.1", 3, "architecture", "Which management group design follows Azure landing zone guidance?", [("Platform (Identity, Management, Connectivity), Landing zones (Corp, Online), Sandbox, Decommissioned", "Correct."), ("One management group per department, mirroring the org chart", "Org charts change; design for policy."), ("Ten nested levels for fine control", "Keep the hierarchy shallow."), ("No management groups; policy per subscription", "Does not scale.")], "a", "The landing zone hierarchy groups subscriptions by the policies and access they need.", ML + "azure/cloud-adoption-framework/ready/landing-zone/design-area/resource-org-management-groups")
qa("AZ305-1.3.2", 2, "scenario", "Auditors need a report showing how Azure resources meet PCI DSS controls. What do you recommend?", [("The Defender for Cloud regulatory compliance dashboard with the PCI DSS standard", "Correct."), ("Azure Advisor", "Best practices, not regulatory mapping."), ("Resource locks", "Do not report."), ("Cost Management", "Costs only.")], "a", "Defender for Cloud maps assessments to regulatory standards.", ML + "azure/defender-for-cloud/regulatory-compliance-dashboard")
qa("AZ305-1.3.2", 2, "scenario", "A company used Azure Blueprints to deploy compliant subscriptions. Blueprints is deprecated. What do you recommend instead?", [("Template specs and deployment stacks with Azure Policy", "Correct."), ("Keep using Blueprints", "Deprecated."), ("Manual portal deployments", "Not repeatable."), ("Resource locks only", "Locks don't deploy anything.")], "a", "Microsoft recommends template specs and deployment stacks (plus policy) to replace Blueprints.", ML + "azure/governance/blueprints/overview")
qa("AZ305-1.3.2", 3, "scenario", "A Deny policy blocks a sandbox team that has an approved, temporary need for public IPs. Others must stay blocked. What do you recommend?", [("A policy exemption (Waiver) on the sandbox scope with an expiry date", "Correct."), ("Delete the policy assignment", "Removes protection for everyone."), ("Change the effect to Audit everywhere", "Weakens enforcement."), ("Give the team Owner", "RBAC doesn't bypass policy.")], "a", "Exemptions exclude a scope from an assignment, with a category and expiry.", GOV + "policy/concepts/exemption-structure")
qa("AZ305-1.3.3", 2, "scenario", "Every quarter, team owners must confirm that guest users still need access to their Microsoft Teams. Unconfirmed guests must lose access. What do you recommend?", [("Access reviews with auto-apply of results", "Correct."), ("PIM", "For privileged roles."), ("Conditional Access", "Controls sign-in, not certification."), ("Dynamic groups", "Membership rules, not reviews.")], "a", "Access reviews certify access and can remove denied users automatically.", ENTRA + "id-governance/access-reviews-overview")
qa("AZ305-1.3.3", 2, "scenario", "Contractors must request a bundle of groups and apps, get manager approval, and lose access automatically after 6 months. What do you recommend?", [("Entitlement management access packages", "Correct."), ("A dynamic group", "No approval or expiry workflow."), ("B2B invitations only", "No bundle or expiry."), ("Administrative units", "Delegation, not access requests.")], "a", "Access packages bundle resources with approval and expiration.", ENTRA + "id-governance/entitlement-management-overview")
qa("AZ305-1.3.3", 2, "scenario", "When HR records an employee's last day, their account should be disabled and removed from groups automatically. What do you recommend?", [("Lifecycle workflows (leaver)", "Correct."), ("Access reviews", "Periodic, not event-driven."), ("Password expiry", "Doesn't remove access."), ("PIM", "For privileged roles.")], "a", "Lifecycle workflows automate joiner, mover and leaver tasks from HR attributes.", ENTRA + "id-governance/what-are-lifecycle-workflows")
